				"name": "MIMK-267",
				"title": "시리즈 누적 판매량 800만 부 카라미자카리 동창회 편 【MOODYZ 창립 25주년 작품】 이시카와 미오",
				"story": "누적 판매 부수 800만 부 돌파! 원작 ‘카라미자카리 3’ 이후 무려 5년 만에 완전 새 작품으로 돌아온 전설적인 동인 만화 ‘카라미자카리 동창회편’을 MOODYZ가 자랑하는 절대적인 에이스 이시카와 미오를 주연으로 맞이해, 세계 최단 시간에 실사 영상화!! 【스토리】 한때 흐릿하고 잔인했던 청소년기의 기억. 나와 타카시. 이이다와 신산. 청춘 시절 얽혔던 우리 인생은 이제 각각 다른 방향으로 나아가고 있다. 사회인이 된 뒤에도 이이다가 어떤 남자에게 안기고 있는지… 그 이야기를 듣고 싶다며 연락을 주고받고, 가끔 만나던 나와 이이다는 사소한 타이밍 차이를 계기로 점점 멀어져 버려, 이제는 계속 연락을 하지 않고 있다…. ●학교를 졸업한 지 13년이 지났다. 손에 동창회 참가 여부를 묻는 메일이 도착해 있다. 이이다도 동창회에 올까…. 지금의 이이다는 어떤 모습일까…. 어딘가에, 어두운 기대를 품고 있는 내가 있었다. 성장했기에 피할 수 없는, 더 깊고 더 진하게 얽히는 야마기시와 이이다의 성향이 어떻게 전개될지. 원작이 지닌 섬세한 심리 묘사와 압도적인 에로스를 이시카와 미오가 몸을 내어 구현한다. 전설의 뒤를 목격하라. 운명이 다시 교차하고, 카라미자카리가 다시 시작된다!",
