				"story": "프레스티지 전속 여배우 「스즈 프레스티지 전속 여배우 「스즈무라 아이리」의 젖은 몸을 사정없이 먹어 치운다….행복한 결혼생활을 하는 아이리는 동네에 사는 동네 회장의 따가운 시선에 고민했다.견디지 못하고 남편과 상의하다 보면 과하게 생각하면 가볍게 떠내려간다.어느 날 쇼핑을 나갔던 아이는 갑작스러운 폭우를 맞아 속옷이 비칠 정도로 흠뻑 젖어버린다.그러자 집 앞에서 마주친 동네 회장이 중요한 이야기가 있다고 해서 거절하지 못하고 방으로 불러들이자 갑자기 덤벼들었다.물이 흠뻑 젖은 치마를 벗기고, 가만히 젖은 온몸을 핥아 음부에 손가락을 넣을 수 있다.이윽고 저항할 힘을 잃은 아이리는, 정말 싫어하는 남자 지●포를 받아 들이고 만다.행복한 신혼살림을 하는 미인아내가 완낙하될 때까지 박살나는 젖은 맨살이 참을 수 없는 전편 젖은 투명 특화형 AV. 본 상품은 2023/07/04 이후 예약주문 분할,묶음,취소가 불가합니다. '묶음/분할' 기능에서 제외된 상품입니다.혜택, 세트 상품 정보 FANZA 한정 혜택이 제공된다!스즈무라 아이리 씨의 A5 포토카드와 특전 DVD가 세트로 구성된 수량 한정판!",
