				"story": "혜택, 세트 상품 정보 【특전 내용】·태피스트리·특전 DVD 특전 포함 상품·세트 상품에 대하여 프레스티지 전속 여배우 「스즈무라 아이리」와 W불륜! 어느 날, 아내가 부재중에 옆으로 넘어 온 젊은 아내·스즈무라씨가 찾아왔다.따끔따끔 다가오는 그녀에게 저항하지만 그녀의 테크닉과 달콤한 유혹을 견디지 못하고 침실에서 행위를 저지르고 만다.쉬는 날은 자택 앞에 스즈무라씨가 차로 찾아와 차내에서 펠라를 뽑았다.그 후에도 현관에서 식스나인과 행위는 그칠 줄 모르고 에스컬레이트! 끝에는 남편이 있는 눈앞에서 들키지 않도록 섹스!서로 몸을 찾아 최고의 쾌락을 맛본다!예쁜 신혼처 『스즈무라 아이리』에 유혹되어 압도적 테크닉의 포로가 되어 간다! ※이 상품은 2024/05/07 이후, 예약 주문의 분할·묶음 또는 취소가 불가능합니다. [묶음/분할]기능을대상에서제외한상품입니다.",
