				"story": "프레스티지 전속 여배우 '스즈모리 레무'가 여동생의 남자친구를 이 손 저 손으로 유혹♪ 그녀의 자택에서 장난을 치는 언니·레무에게 자지 달린 것이 목격되어 버렸다. 약간 낯섬을 느끼면서, 볼 일을 더 보려고 집 안을 걷고 있으니깐, 방에서 자위하는 언니를 조우! 자위를 하고만 있던 언니는, 입막음하기 위해 내 바지를 벗기고 억지로 페라! 여친보다 더 잘하는 언니의 테크닉을 견디지 못하고 발사해버려 이날부터 언니의 무리한 유혹이 시작되고... 어떤 때는 갑자기 집에 들이닥쳐, 전희도 없이 바로 삽입! 또 어떤 때는 그녀가 자는 옆에서 관계를 욕구해 오거나 누나의 유혹은 점점 커져가! 아주 순백바디의 포로가 되어버린 나는, 마음도 몸도 그녀의 누나에게 홀려가고....",
