				"name": "SONE-876",
				"title": "잘때를 제외하고는 항상 복슬복슬 젖어있는 관동1위의 얄리만처! 화려하지만 귀엽고 갸루하지만 근암한 나에게도 야유해줘서 결혼까지 했는데...만나는 남자 모두에게 마음을 터놓는다! 너무 멋져서 귀여워! 쿠라키하나",
				"story": "혜택, 세트 상품 정보 오토나의 썸머 캠페인 2025 8월 5일 아침 10시부터 9월 12일 아침 10시까지 기간 중 S1과 무디스, 마돈나 등 인기 메이커의 대상 상품이 40% 할인!! 또한 기간 중 대상 상품을 구입한 80000명에게는 캠페인걸 엽서(전6종)를 랜덤으로 1장 증정!! ※행사 종료 후, 발송까지 시간이 걸리는 경우, 주문을 분할해 드리는 경우가 있습니다. 미리 양해 부탁드립니다. 혜택이 포함된 상품, 세트 상품에 대해 금발, 날씬, 장신, 초절미형! 분명히 말해 자랑스러운 며느리…였던 지금까지는. 가사 일절 안 하고 요즘 완전 섹스리스. 그러던 어느 날 동료를 데리고 집에 오면 기분 좋게 접대해 주고, 기분 좋게 술에 취하면 내가 못 본 줄 알았는지 동료를 설득하기 시작했다. 도저히 일어날 수 있는 상황이 아니어서 억울하지만 며느리와 동료가 내 옆에서 바람을 피우는 것을 방관(일단 동영상 촬영은 했다). 결혼 당초에는 질질 끌던 그 여자가, 지금의 댓글 상태에 참을 수 있을 리 없다는 것을 깨달은 나는, 집에 카메라를 넣어 보니, 거기에 비쳐져 있던 것은, 집에 오는 남자 전원에게 벌리고 질질 끄는 비치가르가 거기에 있었다.",
