				"story": "아들 부부가 동거해 주다니, 이 얼마나 행복한 사람인가. 그런 생각을 하고 있던 것이 후회될 정도로 며느리가 칠칠치 못하고 건방져. 정리는 안돼, 요리는 꼭지, 장인인 나를 지지라고 불러. 짜증났으니까, 음식이나 스킨크림에 최음약을 숨겨서 건방진 망코를 개발하면, 나의 진보에 푹 빠져, 스스로가 요구하도록. 지금은 아들보다 더 성생활을 구가하고 있다.",
