				"story": "모 상사에 근무하는 아베는 과거 수완가 영업사원이었다. 그러나 시대와 함께 상황은 변화해, 지금까지의 이케이케의 방식으로는 통용되지 않게 되어 있었다. 그리고 깨달았을 때는 정리해고 대상의 창가 샐러리맨으로 전락한다. 자신이 교육한 아카쿠라는 지금은 승진해 직속의 상사와 입장은 역전, 분한 나날을 보내는 아베. 어떻게든 아카쿠라를 깎아내리고 싶은 아베는 어떤 무모한 계획을 생각해 낸다. 그것은 아카쿠라(赤倉)의 약혼자이자 접수양인 카와키타(河北)를 속여서 자신의 것으로 만들겠다는 것이었다. 어떻게든 자신의 것으로 만들고 싶은 아베는 거짓말의 구실로, 억지로 카와키타에게 관계를 강요하지만, 그것을 계기로 카와키타의 안에 감추는 '어떤 버릇'을 찾아내어…",
