				"story": "아무생각없이 믿었던 내가 안이했던... 대학에서 상경해서 혼자 산다. 나름대로 자립할 수 있었다고 생각했다. NO라고 할 수 있는 여성이라고 생각했다. 엄마가 아는 사람이라고 쉽게 신뢰하고 말았다. 거절하기 힘든 상황에서 술을 마시고, 취기가 돌더라도 더 마시라고 부추기고… 정신 차리면 주범격인 남자와 단둘이 당하고… 자꾸 떠내려가고, 정신 차리면 많은 남자에게 둘러싸여 있었다. 알고 보니 많은 남자들이 술자리에 모여 있었다. 여자는 나 혼자뿐이었다. 그런데 이미 나는 술 때문에 정상적인 판단을 할 수 있는 상황이 아니었던 거야. 술에 취해 자고 있는 것도 있고 술에 취해 거리감이 가까운 남자, 지금 생각하면 모두가 나와의 섹스를 속셈으로 노리고 있었던 것이 틀림없다. 도망갈 곳이 없는 좁은 방, 남자들이 일치단결해 술김에 나를 덮친다. 이제 생각을 그만뒀어. 쾌락에 몸을 맡기자. 그리고 오늘 일은 오늘로 잊어버리자...",
