				"story": "어릴 때부터 사이가 좋았던 아야카(彩伽)와 겐이치(健一一). 아야카는 현지에 남아, 켄이치는 취직을 기회로 상경을 하고 있었다. 성인식 만에 재회한 두 사람은 그리움과 함께 서로를 의식하고 있었다. 그것은 두 사람이 사춘기가 되면서 이성으로서 의식하고 있었기 때문에… 하지만 서로 친구라는 관계를 무너뜨리고 싶지 않은 마음에서, '좋아한다'는 마음을 전하지 않고 어른이 되어, 정신을 차리고 보니 소원해져 있었다. 오랜만에 보내는 두 사람의 시간. 기분을 고양시키는 불꽃놀이. '양편애'였던 두 사람의 결말은 어때?",
