				"story": "12월 31일. 연말에 일방적으로 이혼을 요구받아 혼자 외로운 새해 전날을 보내고 있던 기숙사장 나카다. ** 기숙사에 사는 아이들은 모두 실가로 돌아가 버려서 기숙사에는 나만 남았다. 아주 쓸쓸한 연말이다. 둥글게 굽어가기 시작한 등을 어떻게든 버티며 연말에 늘 하던 대청소를 하고 있었는데, 현관에서 소리가 났다. 상황을 보러 가보니 조금 우울해진 아이사이 씨의 모습이 있었다. 비행기 티켓을 잊어버려서 귀가하지 못한 모양이다. 과정은 다르지만, 서로 힘든 연말을 보낸 두 사람만의 ** 기숙사. 사람의 온기가 그리운 계절에 서로가 찾는 것은 따뜻하고 진한 xxx. 우리 아저씨들의 이상적인 섹스 상황을 그린 드라마 작품.",
