				"story": "최악… 게다가 내가 싫어하는 상사와 같은 방을 쓰다니… 수면제를 먹이고 몰래 촬영당해 협박당해 어쩔 수 없이 범죄에 빠진 여성 직원 '리아'. 남자친구의 자지로는 만족할 수 없겠지? 내가 미칠 정도로 오르가즘을 강하게 만들겠어(웃음). 에어컨이 고장 난 객실에서 아침까지 이어지는 추악한 쓰레기 아저씨의 땀에 젖은 격렬한 피스톤! 2발! 3발! 내뱉어도 내뱉어도 쇠퇴하지 않는 절정의 페니스! 이키(이키)할 것 같지? 참을 수 없겠지? 자, 가자! 마음껏 즐겨! 와아아아아! 조용해 보이는 얼굴에 엄청 야한 모습이네 ㅋㅋ 강렬한 쾌감에 아름다운 몸을 뒤로 젖히며 여러 번 절정에 이르게 돼…",
