				"story": "특전·세트 상품 정보 AV 대好き 캠페인 2026년 2월 20일 오전 10시까지, 무디즈·아이디어포켓·어택커스 등 인기 제조사의 대상 상품을 35% 할인!! ※ 캠페인 종료 후 배송까지 시간이 지연될 경우, 주문을 나누어 진행할 수 있습니다. 미리 양해 부탁드립니다. 특전이 포함된 상품·세트 상품에 대하여 아, 아침이구나. 앗, 또 벌거벗은 채로 잠들어버렸네. 음, 오늘 아르바이트 근무가 쉬니까 다시 한 번 잘까. (바스락, 바스락) “아, 선배… 안녕하세요…” …음? …음?? 왜 후배 리아가 내 집에 온 거지? 청소하고 있었어요. 어제 마신 술이나 안주 같은 거… 음? 잘 떠오르지 않아. 그런데 그 쓰레기통에 사용한 고무가 들어 있거든. 리아짱. 미안하지만, 설명해 줄 수 없겠어…? 어제 저녁에 무슨 일이 있었는지. 그리고 가능하다면, 이 흐릿한 기억이 선명해지도록 해줄 수 없겠어??",
