				"title": "빈곤 문제에 힘쓰는 자원봉사 여대생이 지원 현장에서 성 피해를 겪게 된다! 시라카미 사쿠카",
				"story": "사회 봉사 활동에 관심을 가지고 야외 생활자들의 급식 자원봉사에 참여하는 용감한 미소녀. 다른 참가자들이 취업 활동에 유리해지기 위해 참여하는 위선자가 많은 가운데, 진심으로 약자 구제를 꿈꾼다. 하지만 이상과 현실의 차이는 크고, 야외 생활자들의 반감을 사게 된다. 야외 생활자 입장에서는 모두가 위선자로 보이게 된다. ‘그런 봉사 활동을 하고 싶다면 내 자지라도 빨아라’고 억지로 사키카에게 물리게 하고, 팬티도 억지로 벗겨서 혀로 만지며 더럽게 핥는 더러운 어른들. 당연히 저항하지만, 거절하면 위선자로 취급될 것이라 생각해 제대로 거절하지 못한다… 그런 따뜻한 성격이 동료 야외 생활자들에게도 알려져 원●이 되어버렸다….",
