				"story": "현실 사랑으로 일약 유명해진 ** 커플 인플루언서 개화가 장수 마을의 도시 전설을 찾아낸다. 뭔가 그 마을에 간 채로 돌아오지 않게 된 유명 인플루언서가 있다는 것을 알고, 더 인기가 있고 싶은, 승인 욕구가 높아져, 남자친구와 둘이서 마을을 찾는 것에…. 시골 산길에서 좀처럼 찾을 수 없어 현지 행인에게 물어보니 그 마을에 가까이 가지 말라고 화를 낸 모양으로 주의를 받는다! 겁 많은 남자친구를 곁눈질하며 더욱 호기심이 강해진 쇼카는 외딴 마을에서 길을 잃다 낭떠러지에서 떨어져 추락하고 만 두 사람. 의식을 되찾자 아재들에게 둘러싸여, 고택 안에… 염원하던 장수의 마을에 도달한 것이었다. 장수의 비결을 들어보니 아재들이 비법의 액을 보여줬다. 단지 사실은 강력한 최음약이라는 것은 알 길이 없고 호기심 강한 개화는 밤마다 몰래 비전의 액을 마시고 아재들의 덫에 걸려 버린다. 이곳은 장수촌이 아니라 젊은 온나의 진액을 탐닉한 절륜 아재들의 농밀 자맹의 제물이 되는 광기의 취락이었다. 그저 팔로워나 화제성을 만들어 더 유명해지고 싶었을 뿐이었는데. 마을의 음습으로 남자친구 앞에서 키메세쿠 ●로 떨어진 불운한 미소녀 제복 음플앤서.",
