				"story": "혜택, 세트 상품 정보 오토나의 썸머 캠페인 2025 8월 5일 아침 10시부터 9월 12일 아침 10시까지 기간 중 S1과 무디스, 마돈나 등 인기 메이커의 대상 상품이 40% 할인!! 또한 기간 중 대상 상품을 구입한 80000명에게는 캠페인걸 엽서(전6종)를 랜덤으로 1장 증정!! ※행사 종료 후, 발송까지 시간이 걸리는 경우, 주문을 분할해 드리는 경우가 있습니다. 미리 양해 부탁드립니다. 혜택이 포함된 상품, 세트 상품에 대해 【현장에 남겨진 VLOG카메라에 수록되어 있던 초충격 영상】최초로 찍혀 있던 것은, 여대생의 웃는 얼굴이었다. 목욕 후의 뺨, 들뜬 목소리, 여자 여행의 공기. 브이로그용으로 돌리던 카메라는 여행의 추억을 남길 터였다. 하지만, 폐허에 발을 들이는 순간부터 영상은 바뀌어 간다. 흐트러진 숨소리, 흔들리는 화면, 떨리는 목소리. 그리고 울면서도 쾌감에 허덕이는 그녀의 모습. 도망쳐도 도망쳐도 쾌락은 멈추지 않았다. 이거 연출이야? 기록인가? 아무도 말리지 않은 카메라가 마지막까지 모든 것을 비추고 있었다.",
