				"story": "처음으로 그녀의 집에 묵으러 갔다. 무방비 상태로 선잠을 자는 여동생 사키하나의 치마에서 들여다보는 가녀린 허벅지에 시선이 쏠린다. 투명한 피부, 가늘고 부드러운 발목. 그 미성숙한 몸에 살짝 손끝이 닿는 순간, 움찔하며 몸을 움츠리는 꽃송이. 「다, 안 돼…」라고 겁에 질린 목소리, 촉촉해지는 눈동자, 가는 팔로 필사적으로 되밀어내려는 몸짓이 점점 이성을 무너뜨려 간다. 그 미덥지 못한 힘이 역으로 나의 욕망을 부추겼고, 정신 차리면 그 어깨를 짓누르고 있었다. 이윽고 희미하게 떨며 내 팔에 매달리듯 손가락을 얽고, 얇게 벌린 입술에서는 달콤한 입김이 새어나오기 시작한다. 서투른 반응이 참을 수 없이 사랑스럽고, 정신 차리면 그 가녀린 몸을 몇 번이고 탐하고 있어……………………. 되돌릴 수 없다.",
