				"story": "특전 · 세트 상품 정보 GW대감사제 20254월 22일 아침 10시부터 5월 16일 아침 10시까지 기간 중, S1이나 무디스, 마돈나 인기 메이커의 대상 상품이 35% 할인! 또한 대상 Blu-ray 디스크 온디맨드 상품이 세금 포함 1540엔!! ※행사 종료 후, 발송까지 시간이 걸리는 경우, 주문을 분할해 드리는 경우가 있습니다. 미리 양해 부탁드립니다. 혜택이 포함된 상품, 세트 상품에 대해 얼마 전까지 오빠와 프로 레슬링 놀이를 해서 지고 있던 여동생인 나. 나는 형을 이긴적이 없어. 억울해. 너무 억울해. 시·카·시! 최근에 나는 남사친이 여자 팬티를 보고 흥분을 하는 것을 목격했다. 이거는 혹시... 형도 흥분해서 이상해지지 않을까? 어느 날, 형에게 펀치 해보니… 초살로 이길 수 있었다. 사키하나 너무 오빠 얕보는 거 아니야. 팬티를 숨겨라…」ㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋ숨길 리가 없잖아ㅋㅋㅋㅋㅋ팬티를 보여줄 때마다 덤벼들어 장난치는 형. 오빠, 멋쟁이 ㅎㅎ 근데! 금단의 남매 섹스, 아리카모! ※ 개화의, 팬티의 살갗을 파고드는 것과, 팬티에서 튀어나온 흰 피부, 너무 야한 주의입니다※",
