				"story": "어느 날, 나는 여**과 만나기로. 이른바 아빠활이다. 그 여자는 너무 '소금 대응'으로… 돈을 지불하고 있는데 감정이 없는 손 코키와 페라치오. 뭐야, 이 녀석은. 화가 난 나는 억지로 최음약을 ● 시켜 호텔에서 현실사회를 가르쳐 주었다. 최음약은 대단한데. 이런 무뚝뚝한 여자도, 이 최음약이 있으면, 경련해 신나게 된다. 몸을 젖히고 '으으... 헉헉헉헉 헐떡이고 있어. 오늘의 아빠 활동은 만족이다.",
