				"story": "지방 출신인 나는 대학 입학으로 상경했다. 익숙하지 않은 도쿄. 아는 사람의 소개로 라운지의 아르바이트를 시작하는 것도... 접객에 익숙하지 않고... 어느날, 성실하고 상냥한 손님(아저씨)에게... 나는 사랑을 하고 말았다. 그 손님과 가게 밖 데이트를 했는데 막차도 없이 근처 호텔에 묵기로 했다. 그러나 설마 한 방만 비어 있고. '손님과 단둘이 있을 수 있다'는 생각에 나는 한 방(다인실)도 괜찮다고 전했다. 상대는 아저씨로 기혼자. 절대 안 돼. 손님들도 같은 생각을 하고 있을 것이다. 하지만 나는 참지 못하고... 손님에게 키스를 해버려서... 나는 그 후 50대 아저씨와 몇 번이고 요청했고, 아침을 맞이할 때까지 섹스를 반복했다.",
