				"story": "혜택, 세트 상품 정보 겨울 BIG 세일 1탄! 11월 22일부터 12월 19일 아침 10시까지 기간 중 SOD 크리에이트와 FALENO, 프레스티지, 화보 대상 상품이 40% 할인!! ※BIG세일제2탄은 12월 10일부터 진행※캠페인 종료 후, 발송까지 시간이 걸리는 경우, 주문을 분할해 드리는 경우가 있습니다. 미리 양해 부탁드립니다. 혜택이 포함된 상품, 세트 상품에 대해 결혼하고 집을 나간 언니가 남편과 싸우고 친정으로 돌아왔다. 나에게는 좋아하는 여자가 있어서, 어떻게든 키스하고 싶었지만 차버렸다. '언니, 키스하게 해줘' 허를 찔린 언니는 키스를 허락했고, 게다가 진보를 손으로 쓱싹싹싹 안아줬다. 누나에 대한 욕정을 주체할 수 없게 된 나는 몇 번이나 키스를 하며 첫 체험을 바쳤다.",
