				"name": "MIDA-610",
				"title": "너를 좋아해. ** 시절 사귀던 여자친구와 우연히 재회. 쓰레기 남자친구와 사귀었지만 나는 그녀와 여러 번 섹*를 했어",
				"story": "** 시절, 우리는 사귀고 있었다. 사귀고 있었지만, 아직 섹스는 하지 않았다. 졸업하기 전에, 그녀에게 이별을 통보받았다. 그녀의 나체를 보지 못한 채, 흐릿한 청춘의 사랑 이야기가 끝났다—그녀는 대학에 진학하고, 나는 방송국 AD가 되었다. 바쁜 일상에 그녀를 잊어가고 있었지만, 우연히 재회—. 조금 어른스러워진 그녀. 남자친구 같은 사람은 있는 것 같아…. 바에서 함께 술을 마시고 돌아오는 길에, 역까지 달리면 막차에 맞출 수 있을 것 같았지만, 그녀가 말했다. “오늘, 네 집에 자도 될까?”",
