				"story": "최강 히로인에게 강간●하고 싶어… 유연한 손끝으로 가슴을 자극당하면서 귀 옆에서 속삭이고 싶어… 키스하고 싶어? 아직 안 돼. 몸도 마음도 완전히 지배당하고 싶어… 같이 목욕하면서 몸을 붙이고, 천천히 놀리면서 괴롭히고 싶어… 여러 번 절정에 이르려는 걸 막고, 머리가 이상해질 때까지 가지고 놀리고 싶어… 깨끗한 엉덩이로 남자를 끼고, 위아래로 움직이며 문질러서 그대로 한심하게 절정에 이르고 싶어… 순수한 세토칸에게 목걸이를 달고 애완동물처럼 대우받고 싶어… '귀엽다'는 말을 들으며 몰입해서 허리를 굽힌 뒤 봉사 섹스를 하고 싶고… 최강 히로인에게 24시간 강간●하고 싶다… 그런 욕망을 모두 들어줄 AV입니다.",
